/// Sleeps for the specified duration.
///
/// # Errors
///
/// This call will fail if creating or initializing the underlying timer fails,
/// or if `duration`'s representation in milliseconds cannot be cast as `u32`.
pub async fn sleep(duration: Duration) -> Result<(), nsresult> {
    SleepTimerFuture(SleepTimer::with_duration(duration)?).await;

    Ok(())
}

/// A newtype wrapper around the timer to allow us to implement traits on it.
struct SleepTimerFuture(RefPtr<SleepTimer>);

/// A timer for
#[xpcom::xpcom(implement(nsITimerCallback), atomic)]
struct SleepTimer {
    /// The backing XPCOM timer instance.
    ///
    /// We must hold a reference to it until we are notified that it has
    /// completed.
    timer: RefPtr<nsITimer>,

    /// Whether the timer has notified us of completion.
    has_timer_completed: Cell<bool>,

    /// The task waker to wake when ready, if any.
    waker: Cell<Option<Waker>>,
}

impl SleepTimer {
    /// Creates a new sleep timer with the specified duration.
    fn with_duration(duration: Duration) -> Result<RefPtr<Self>, nsresult> {
        let timer = xpcom::create_instance::<nsITimer>(c"@mozilla.org/timer;1")
            .ok_or(NS_ERROR_UNEXPECTED)?;

        let sleeper = Self::allocate(InitSleepTimer {
            timer: timer.clone(),
            has_timer_completed: Default::default(),
            waker: Default::default(),
        });

        // `timer.InitWithCallback` expects an amount of milliseconds as an
        // `u32` so we need it to be low enough to fit in one.
        let duration: u32 = duration
            .as_millis()
            .try_into()
            .or(Err(NS_ERROR_INVALID_ARG))?;

        unsafe {
            timer.InitWithCallback(sleeper.coerce(), duration, nsITimer::TYPE_ONE_SHOT as u32)
        }
        .to_result()?;
